import React from "react";

function MsgHistory({ datetime, email, msg }) {
  const headers = ["Date", "Message"];
  return (
    <table className=" flex  te">
      <thead>
        <tr>
          {headers.map((h) => {
            return <td>{h}</td>;
          })}
        </tr>
      </thead>
    </table>
  );
}

export default MsgHistory;
